const createActivatedR12bReader = (): ((relative: string) => Buffer) => {
  const successorPath = path.join(backendRoot, 'architecture/r12c-zero-cross-context-dependencies.json');
  if (!existsSync(successorPath)) {
    return (relative: string) => Buffer.from(
      readFileSync(path.join(repositoryRoot, ...relative.split('/'))),
    );
  }
  const successor = JSON.parse(readFileSync(successorPath, 'utf8'));
  const r12c = require(path.join(backendRoot, 'scripts/architecture/r12c-zero-cross-context-dependencies-scan.cjs'));
  const predecessor = r12c.projectR12cWorkingTreeToPredecessor({ repositoryRoot, manifest: successor });
  return (relative: string) => {
    const bytes = predecessor.readWorkingFile(relative);
    assert.equal(Buffer.isBuffer(bytes), true, `R12C predecessor projection is missing ${relative}`);
    return Buffer.from(bytes);
  };
};
