test('R12B bounded hunk schema rejects obsolete, partial, malformed, and unregistered registrations', () => {
  const api = scanner();
  const entry = Buffer.from('a=1;\r\nb=2;\r\n', 'utf8');
  const final = Buffer.from('أ\na=7;\r\n', 'utf8');
  const inverse = {
    path: 'backend/scripts/architecture/r5-identity-scan.cjs', entrySha256: hashBytes(entry),
    kind: 'bounded-hunk-replay', intendedFinalSha256: hashBytes(final),
    payload: { entryByteLength: 12, hunks: [
      { offset: 0, before: '', after: 'أ\n' },
      { offset: 2, before: '1', after: '7' },
      { offset: 6, before: 'b=2;\r\n', after: '' },
    ] },
  };
  const cases: Array<[string, (value: any) => void, Buffer]> = [
    ['negative offset', (v) => { v.payload.hunks[0].offset = -1; }, entry],
    ['fractional offset', (v) => { v.payload.hunks[0].offset = 0.5; }, entry],
    ['unsafe offset', (v) => { v.payload.hunks[0].offset = Number.MAX_SAFE_INTEGER + 1; }, entry],
    ['duplicate offset', (v) => { v.payload.hunks[1].offset = 0; }, entry],
    ['reversed hunks', (v) => { v.payload.hunks.reverse(); }, entry],
    ['overlap', (v) => { v.payload.hunks[1] = { offset: 2, before: '1;', after: '7' }; v.payload.hunks[2].offset = 3; }, entry],
    ['before past entry', (v) => { v.payload.hunks[2].offset = 11; }, entry],
    ['oversized entry', (v) => { v.payload.entryByteLength = 2097153; }, entry],
    ['empty hunks', (v) => { v.payload.hunks = []; }, entry],
    ['sparse hunks', (v) => { v.payload.hunks = new Array(1); }, entry],
    ['too many hunks', (v) => { v.payload.hunks = Array.from({ length: 129 }, () => ({ offset: 0, before: '', after: 'x' })); }, entry],
    ['unknown payload key', (v) => { v.payload.extra = true; }, entry],
    ['unknown hunk key', (v) => { v.payload.hunks[0].extra = true; }, entry],
    ['no-op text', (v) => { v.payload.hunks[1].after = '1'; }, entry],
    ['unpaired surrogate', (v) => { v.payload.hunks[0].after = '\ud800'; }, entry],
    ['wrong final hash', (v) => { v.intendedFinalSha256 = 'f'.repeat(64); }, entry],
    ['wrong replacement bytes', (v) => { v.payload.hunks[1].after = '8'; }, entry],
    ['non-handoff path', (v) => { v.path = 'backend/package.json'; }, entry],
  ];
  for (const [label, change, bytes] of cases) {
    const changed = structuredClone(inverse);
    change(changed);
    assert.throws(() => api.applyR12bHunkTransform({ bytes, inverse: changed, direction: 'forward' }), label);
  }
  const partial: any = structuredClone(inverse);
  partial.payload.hunks = null;
  assert.throws(() => api.applyR12bHunkTransform({ bytes: entry, inverse: partial, direction: 'forward' }));
  const oldSchema = mutate(loadManifest(), (value) => { value.schemaVersion = 1; });
  assert.throws(() => api.validateR12bManifest(oldSchema), /schema version/u);
  const oldKind = mutate(loadManifest(), (value) => {
    const item = value.inverseTransforms[3];
    item.kind = 'bounded-insertion-removal';
    item.payload = { startMarker: 'x', endMarker: 'y' };
  });
  assert.throws(() => api.validateR12bManifest(oldKind), /kind/u);
});

