test('R12B preregistration validates a registered candidate while its entry bytes remain published', () => {
  const api = scanner();
  const pending = strictProjection(loadManifest());
  const pendingFixture = projectFixture(pending);
  const pendingInverse = pending.inverseTransforms.find((item: any) => item.path === 'backend/scripts/architecture/r5-identity-scan.cjs');
  pendingInverse.payload.entryByteLength = null;
  pendingInverse.payload.hunks = null;
  pendingInverse.intendedFinalSha256 = null;
  finalizeR12bPathContracts(pending, pendingFixture.files);
  const pendingEntry = pendingFixture.files.get(pendingInverse.path)!;
  pendingFixture.files.set(pendingInverse.path, Buffer.concat([pendingEntry, Buffer.from('unknown', 'utf8')]));
  assert.throws(() => api.projectR12bWorkingTreeToPredecessor({
    repositoryRoot, manifest: pending, statusRows: pendingFixture.statusRows,
    readWorkingFile: (relative: string) => pendingFixture.files.get(relative),
    pathExists: (relative: string) => pendingFixture.files.has(relative),
  }), /predecessor path drifted/u, 'changed pending bytes must fail');

  const manifest = strictProjection(loadManifest());
  const fixture = projectFixture(manifest);
  const inverse = manifest.inverseTransforms.find((item: any) => item.path === 'backend/scripts/architecture/r5-identity-scan.cjs');
  const entry = fixture.files.get(inverse.path)!;
  const after = '\n// approved\n';
  const candidate = Buffer.concat([entry, Buffer.from(after, 'utf8')]);
  inverse.payload = {
    entryByteLength: entry.length,
    hunks: [{ offset: entry.length, before: '', after }],
  };
  inverse.intendedFinalSha256 = hashBytes(candidate);
  finalizeR12bPathContracts(manifest, fixture.files);
  const project = (value = manifest) => api.projectR12bWorkingTreeToPredecessor({
    repositoryRoot, manifest: value, statusRows: fixture.statusRows,
    readWorkingFile: (relative: string) => fixture.files.get(relative),
    pathExists: (relative: string) => fixture.files.has(relative),
  });
  assert.doesNotThrow(project, 'registered candidate must validate before publication');

  const partial = structuredClone(manifest);
  const partialInverse = partial.inverseTransforms.find((item: any) => item.path === inverse.path);
  partialInverse.payload.hunks = null;
  assert.throws(() => project(partial), /partial|hunk/u, 'partial registration must fail closed');

  inverse.payload.hunks[0].after = '\n// approveD\n';
  assert.throws(project, /result hash|hunk replay/u, 'bad preregistration must fail while entry remains live');
  inverse.payload.hunks[0].after = after;
  fixture.files.set(inverse.path, Buffer.concat([entry, Buffer.from('unknown', 'utf8')]));
  assert.throws(project, /final hash|predecessor path drifted/u, 'unknown edit before publication must fail');
  fixture.files.set(inverse.path, candidate);
  assert.doesNotThrow(project, 'exact registered candidate must pass after publication');
  inverse.payload.hunks[0].after = '\n// approveD\n';
  assert.throws(project, /hunk slice/u, 'same-length registered-content tamper must fail at projection');
});

test('R12B replays adjacent deletions and unequal replacement byte lengths in both directions', () => {
  const api = scanner();
  const entry = Buffer.from('AéBCD\r\nEFG', 'utf8');
  const final = Buffer.from('ALONGD\r\nEFG', 'utf8');
  const inverse = {
    path: 'backend/scripts/architecture/r5-identity-scan.cjs', entrySha256: hashBytes(entry),
    kind: 'bounded-hunk-replay', intendedFinalSha256: hashBytes(final),
    payload: { entryByteLength: entry.length, hunks: [
      { offset: 1, before: 'é', after: '' },
      { offset: 3, before: 'B', after: '' },
      { offset: 4, before: 'C', after: 'LONG' },
    ] },
  };
  assert.deepEqual(api.applyR12bHunkTransform({ bytes: entry, inverse, direction: 'forward' }), final);
  assert.deepEqual(api.applyR12bHunkTransform({ bytes: final, inverse, direction: 'inverse' }), entry);
  assert.throws(() => api.applyR12bHunkTransform({ bytes: Buffer.from('wrong', 'utf8'), inverse, direction: 'forward' }), /input hash|length/u);
  const wrongEntry = structuredClone(inverse);
  wrongEntry.entrySha256 = 'f'.repeat(64);
  assert.throws(() => api.applyR12bHunkTransform({ bytes: entry, inverse: wrongEntry, direction: 'forward' }), /input hash/u);
  assert.throws(() => api.applyR12bHunkTransform({ bytes: Buffer.from('ALONgD\r\nEFG', 'utf8'), inverse, direction: 'inverse' }), /input hash/u);
  const wrongSlice = structuredClone(inverse);
  wrongSlice.payload.hunks[2].after = 'LOnG';
  assert.throws(() => api.applyR12bHunkTransform({ bytes: final, inverse: wrongSlice, direction: 'inverse' }), /slice/u);
  const splitUtf8 = {
    path: inverse.path, entrySha256: hashBytes(Buffer.from('é', 'utf8')),
    kind: 'bounded-hunk-replay', intendedFinalSha256: 'a'.repeat(64),
    payload: { entryByteLength: 2, hunks: [{ offset: 1, before: '', after: 'x' }] },
  };
  assert.throws(() => api.applyR12bHunkTransform({ bytes: Buffer.from('é', 'utf8'), inverse: splitUtf8, direction: 'forward' }), /exact UTF-8/u);
});

